<?php require_once __DIR__.'/../includes/functions.php';role('student');$cid=(int)($_GET['id']??0);$sid=$_SESSION['user_id'];$s=$conn->prepare('SELECT c.*,u.name teacher FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN users u ON u.id=c.teacher_id WHERE e.course_id=? AND e.student_id=?');$s->bind_param('ii',$cid,$sid);$s->execute();$course=$s->get_result()->fetch_assoc();if(!$course)exit('You are not enrolled in this class.');$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$aid=(int)$_POST['assignment_id'];$txt=trim($_POST['response_text']??'');$q=$conn->prepare('SELECT id FROM assignments WHERE id=? AND course_id=?');$q->bind_param('ii',$aid,$cid);$q->execute();if(!$q->get_result()->fetch_assoc())$err='Invalid assignment.';else try{$f=upload_one($_FILES['submission_file']??null,'submissions');if($txt===''&&!$f)throw new RuntimeException('Write a response or attach a file.');$on=$f['original_name']??null;$sn=$f['stored_name']??null;$mt=$f['mime_type']??null;$sz=$f['file_size']??null;$q=$conn->prepare('INSERT INTO submissions(assignment_id,student_id,response_text,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE response_text=VALUES(response_text),original_name=COALESCE(VALUES(original_name),original_name),stored_name=COALESCE(VALUES(stored_name),stored_name),mime_type=COALESCE(VALUES(mime_type),mime_type),file_size=COALESCE(VALUES(file_size),file_size),submitted_at=CURRENT_TIMESTAMP');$q->bind_param('iissssi',$aid,$sid,$txt,$on,$sn,$mt,$sz);$q->execute();$msg='Assignment submitted successfully.';}catch(Throwable $x){$err=$x->getMessage();}}
$q=$conn->prepare('SELECT * FROM announcements WHERE course_id=? ORDER BY created_at DESC');$q->bind_param('i',$cid);$q->execute();$anns=$q->get_result();$q=$conn->prepare('SELECT * FROM materials WHERE course_id=? ORDER BY uploaded_at DESC');$q->bind_param('i',$cid);$q->execute();$mats=$q->get_result();$q=$conn->prepare('SELECT a.*,s.id sub_id,s.response_text,s.original_name FROM assignments a LEFT JOIN submissions s ON s.assignment_id=a.id AND s.student_id=? WHERE a.course_id=? ORDER BY a.created_at DESC');$q->bind_param('ii',$sid,$cid);$q->execute();$ass=$q->get_result();$page_title=$course['title'];include __DIR__.'/../includes/header.php';?><p><a href="courses.php">← My classes</a></p><h1><?=e($course['title'])?></h1><p class="muted">Teacher: <?=e($course['teacher'])?></p><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><div class="grid two"><div class="card"><h2>Announcements</h2><?php while($a=$anns->fetch_assoc()):?><p><b><?=e($a['title'])?></b><br><?=nl2br(e($a['body']))?></p><hr><?php endwhile;?></div><div class="card"><h2>Learning materials</h2><?php while($m=$mats->fetch_assoc()):?><p>📎 <?=e($m['original_name'])?> · <a href="<?=BASE_URL?>/download.php?type=material&id=<?=$m['id']?>">Download</a></p><?php endwhile;?></div></div><h2>Assignments</h2><?php while($a=$ass->fetch_assoc()):?><div class="card"><h3><?=e($a['title'])?> <?php if($a['sub_id']):?><span class="badge">Submitted</span><?php endif;?></h3><p><?=nl2br(e($a['instructions']))?></p><p class="muted">Due: <?=e($a['due_date']?:'No due date')?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="assignment_id" value="<?=$a['id']?>"><label>Your response</label><textarea name="response_text" placeholder="Write your answer..."><?=e($a['response_text']??'')?></textarea><label>Attach assignment file (optional)</label><input type="file" name="submission_file"><p class="muted tiny">Maximum 10 MB · PDF, Office files, images, TXT, ZIP</p><button class="btn">Submit assignment</button></form><?php if($a['original_name']):?><p class="muted tiny">Attached: <?=e($a['original_name'])?></p><?php endif;?></div><?php endwhile;?><?php include __DIR__.'/../includes/footer.php';?>
